package com.mybank.pbac.service;
import com.mybank.pbac.dto.PolicyRequest; import com.mybank.pbac.model.*; import com.mybank.pbac.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class PolicyService{private final PolicyRepository policies;private final ObligationRepository obligations;private final IndustryRepository industries;private final AuditService audit;
 public PolicyService(PolicyRepository p,ObligationRepository o,IndustryRepository i,AuditService a){policies=p;obligations=o;industries=i;audit=a;}
 public List<Policy> all(Long industryId,GuardrailType guardrail,Boolean enabled,String q){return policies.search(industryId,guardrail,enabled,q==null||q.isBlank()?null:q.trim());} public Policy one(Long id){return policies.findById(id).orElseThrow(()->new NoSuchElementException("Policy not found"));}
 @Transactional public Policy save(Long id,PolicyRequest r){Policy p=id==null?new Policy():one(id);p.setCode(r.code());p.setName(r.name());p.setDescription(r.description());p.setEffect(r.effect());p.setConditionLogic(r.conditionLogic()==null?LogicalOperator.AND:r.conditionLogic());p.setPriority(r.priority()==null?100:r.priority());p.setEnabled(r.enabled()==null||r.enabled());p.setIndustry(industries.findById(r.industryId()).orElseThrow(()->new NoSuchElementException("Industry not found")));p.setGuardrailType(r.guardrailType());p.setGuardrailSubtype(r.guardrailSubtype());
  p.getConditions().clear();if(r.conditions()!=null){int n=0;for(var x:r.conditions()){var c=new PolicyCondition();c.setAttributeKey(x.attributeKey());c.setOperator(x.operator());c.setExpectedValue(x.expectedValue());c.setSequenceNo(x.sequenceNo()==null?n:x.sequenceNo());p.getConditions().add(c);n++;}}
  var selected=new LinkedHashSet<Obligation>();if(r.obligationIds()!=null)selected.addAll(obligations.findAllById(r.obligationIds()));if(p.getEffect()==PolicyEffect.PERMIT_WITH_OBLIGATIONS&&selected.isEmpty())throw new IllegalArgumentException("PERMIT_WITH_OBLIGATIONS requires at least one obligation");p.getObligations().clear();p.getObligations().addAll(selected);if(id==null)p=policies.save(p);else policies.flush();audit.log(id==null?"CREATE":"UPDATE","POLICY",p.getId(),p.getCode());return p;}
 @Transactional public void delete(Long id){Policy p=one(id);policies.delete(p);audit.log("DELETE","POLICY",id,p.getCode());}}
